public class AreaEngine {
    // 1. Square: 1 int parameter
    public static int calculateArea(int side) {
        System.out.println("-> Invoked Square calculateArea(int)");
        return side * side;
    }

    // 2. Rectangle: 2 int parameters
    public static int calculateArea(int length, int width) {
        System.out.println("-> Invoked Rectangle calculateArea(int, int)");
        return length * width;
    }

    // 3. Circle: 1 double parameter
    public static double calculateArea(double radius) {
        System.out.println("-> Invoked Circle calculateArea(double)");
        return 3.14159 * radius * radius;
    }

    public static void main(String[] args) {
        System.out.println("Square Area: " + calculateArea(5));
        System.out.println("Rectangle Area: " + calculateArea(4, 6));
        System.out.println("Circle Area: " + calculateArea(3.0));
    }
}

