public class Main {
    public static void repeatPrint(String msg) {
        repeatPrint(msg, 1);
    }

    public static void repeatPrint(String msg, int count) {
        for (int i = 0; i < count; i++) {
            System.out.println(msg);
        }
    }

    public static void main(String[] args) {
        repeatPrint("Hi");
        repeatPrint("Java", 3);
    }
}

