practiceProblems.solutionCode:
public class Main {
    public static double calcTotal(double price) {
        return calcTotal(price, 1, 0.0);
    }

    public static double calcTotal(double price, int qty) {
        return calcTotal(price, qty, 0.0);
    }

    public static double calcTotal(double price, int qty, double discountRate) {
        return (price * qty) * (1.0 - discountRate);
    }

    public static void main(String[] args) {
        System.out.println("Single item: $" + calcTotal(50.0));
        System.out.println("3 items: $" + calcTotal(50.0, 3));
        System.out.println("3 items 10% off: $" + calcTotal(50.0, 3, 0.10));
    }
}

