public class Main {
    public static boolean matches(String text, char target) {
        return text.indexOf(target) != -1;
    }

    public static boolean matches(String text, String target) {
        return text.contains(target);
    }

    public static void main(String[] args) {
        System.out.println("Matches 'v': " + matches("Java", 'v'));
        System.out.println("Matches 'By': " + matches("LearnBySelf", "By"));
    }
}
